import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int r = sc.nextInt();
            double perimeter = 2.0 * Math.PI * r;
            System.out.printf("%.6f\n", perimeter);
        }
    }
}

